var layer = tree.root.get_node("Main").get_node("BoardRoot/TokenLayer")
var marked := {}
var ork_marked := 0
for c in layer.get_children():
	if not c.has_meta("unit_id"):
		continue
	var uid := str(c.get_meta("unit_id"))
	var u = GameState.get_unit(uid)
	if bool(c.get("katah_readied_marker")):
		if int(u.get("owner", 0)) == 2:
			ork_marked += 1
		else:
			marked[uid] = true
print("[cus11e marker] readied-badge units: ", marked.keys(), " ork badges: ", ork_marked)
return marked.size() == 9 and ork_marked == 0

var layer = tree.root.get_node("Main").get_node("BoardRoot/TokenLayer")
var cg_marked := 0
var cg_tokens := 0
var sc_marked := 0
for c in layer.get_children():
	if not c.has_meta("unit_id"):
		continue
	var uid := str(c.get_meta("unit_id"))
	if uid == "U_CUSTODIAN_GUARD_B":
		cg_tokens += 1
		if bool(c.get("katah_readied_marker")):
			cg_marked += 1
	elif uid == "U_SHIELD_CAPTAIN_A" and bool(c.get("katah_readied_marker")):
		sc_marked += 1
print("[cus11e marker] after Conservai: CG tokens=", cg_tokens, " CG badges=", cg_marked, " SC badges=", sc_marked)
return cg_tokens == 3 and cg_marked == 0 and sc_marked == 1

var t = tree.root.get_node("Main")._token_hover_label
if t == null:
	return "no hover label"
var s: String = t.get_parsed_text()
print("[cus11e marker] hover after Conservai: ", s)
return s.contains("CONSERVAI") and not s.contains("Readied")
